build.buildCommand:
cat >> src/ui/styles.css <<'EOF'

/* 凭证设置 */
.cred-list { list-style:none; margin:8px 0 0; padding:0; }
.cred { padding:8px 0; border-bottom:1px solid #2a2a2c; }
.cred-head { display:flex; justify-content:space-between; margin-bottom:6px; }
.cred-form { display:flex; gap:6px; }
.cred-form input { flex:1; background:#252527; color:var(--fg); border:1px solid var(--line); border-radius:6px; padding:6px 8px; font:inherit; }
.cred-form button { padding:0 12px; border:1px solid var(--line); border-radius:6px; }
EOF
npm run build 2>&1 | grep -v '^npm notice' | tail -5
echo "=== 冒烟：起 app 看有没有报错 ==="
( npx electron dist/electron/main.js > /tmp/dawn-app2.log 2>&1 & echo $! > /tmp/dawn-app2.pid )
for i in $(seq 1 8); do sleep 1; done
PID=$(cat /tmp/dawn-app2.pid); pkill -P "$PID" 2>/dev/null; kill "$PID" 2>/dev/null; sleep 1
grep -v 'SIGTERM\|npm notice' /tmp/dawn-app2.log | head -10; echo "（以上无输出即为无报错）"

build.testCommand:
python3 - <<'PYEOF'
import pathlib
p = pathlib.Path("src/ui/App.tsx")
s = p.read_text()

s = s.replace('import { ConversationView, SessionSidebar, TerminalDock, type Turn } from "./views.js"',
              'import { ConversationView, SessionSidebar, TerminalDock, type Turn } from "./views.js"\n'
              'import { SettingsPanel, type CredentialState } from "./Settings.js"')

s = s.replace('''  const [sidebar, setSidebar] = useState(false) // 默认 agent-first：侧栏收起''',
'''  const [creds, setCreds] = useState<CredentialState>({ configured: [], encrypted: false })
  const [endpoints, setEndpoints] = useState<string[]>([])
  const [showSettings, setShowSettings] = useState(false)

  const [sidebar, setSidebar] = useState(false) // 默认 agent-first：侧栏收起''')

s = s.replace('''  const refreshProjects = useCallback(() => {
    client.get<ProjectSummary[]>("listProjects").then(setProjects).catch(fail)
  }, [client, fail])''',
'''  const refreshProjects = useCallback(() => {
    client.get<ProjectSummary[]>("listProjects").then(setProjects).catch(fail)
  }, [client, fail])

  const refreshCreds = useCallback(() => {
    client.get<CredentialState>("listCredentials").then(setCreds).catch(fail)
  }, [client, fail])''')

s = s.replace('''  useEffect(() => {
    if (ready) refreshProjects()
  }, [ready, refreshProjects])''',
'''  useEffect(() => {
    if (!ready) return
    refreshProjects()
    refreshCreds()
    // endpoint 清单来自 capabilities 之外的一次查询；①-B 先从 listCredentials
    // 的已配置项 + 一个静态兜底推导，等 providers 暴露到协议后再改
    client
      .get<{ configured: string[] }>("listCredentials")
      .then((c) => setEndpoints((e) => [...new Set([...e, ...c.configured, "deepseek"])]))
      .catch(fail)
  }, [ready, refreshProjects, refreshCreds, client, fail])''')

s = s.replace('''        <button type="button" onClick={() => setSidebar((v) => !v)}>
          {sidebar ? "隐藏侧栏" : "显示侧栏"}
        </button>''',
'''        <button type="button" onClick={() => setSidebar((v) => !v)}>
          {sidebar ? "隐藏侧栏" : "显示侧栏"}
        </button>
        <button type="button" onClick={() => setShowSettings((v) => !v)}>
          {showSettings ? "返回" : "设置"}
        </button>''')

s = s.replace('''        <main className="main">
          {session ? (''',
'''        <main className="main">
          {showSettings ? (
            <div className="panels">
              <SettingsPanel
                endpoints={endpoints}
                credentials={creds}
                onSet={(id, secret) => {
                  client
                    .get("setCredential", { endpointId: id, secret })
                    .then(refreshCreds)
                    .catch(fail)
                }}
                onDelete={(id) => {
                  client.get("deleteCredential", { endpointId: id }).then(refreshCreds).catch(fail)
                }}
              />
            </div>
          ) : session ? (''')

s = s.replace('''            <div className="panels">
              <StatusPanel sessions={sessions} />''',
'''            <div className="panels">
              {creds.configured.length === 0 ? (
                <section className="panel">
                  <h3 className="panel-title">先配置凭证</h3>
                  <div className="panel-body">
                    <p className="caveat">
                      还没有配置任何 API key —— native agent 无法建会话。点顶栏「设置」填写。
                    </p>
                  </div>
                </section>
              ) : null}
              <StatusPanel sessions={sessions} />''')
p.write_text(s)
print("App 已接入设置")
PYEOF
npm run typecheck 2>&1 | grep -v '^npm notice' | head -5; echo "--- typecheck ---"; npx vitest run 2>&1 | tail -5
